/* Generated by Trae Work */
/* 学习状态监视页：只读，订阅 ntfy.sh 私有频道（SSE 实时推送），显示最新打卡快照 */
"use strict";
(function () {
  const CLOUD = "https://ntfy.sh";
  let es = null;
  let latest = null;

  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  function render() {
    if (!latest) return;
    const root = document.getElementById("status-root");
    const meta = document.getElementById("status-meta");
    const s = latest.summary || {};
    meta.textContent = `更新时间：${esc(latest.updated_at)} · 数据日期：${esc(latest.date)} · 实时连接中`;
    const lessons = (latest.lessons || []).map(l => `
      <div class="plan-lesson ${l.track || ""} ${l.status}">
        <div class="pl-head">
          <span class="pl-time">${esc(l.time || "")}</span>
          <div class="pl-goal"><div class="pl-goal-text">${esc(l.label || "")}</div></div>
          <span class="badge ${l.status === "done" ? "ok" : l.status === "skipped" ? "miss" : "warnb"}">${l.status === "done" ? "已完成" : l.status === "skipped" ? "已跳过" : "进行中/待完成"}</span>
        </div>
        <div class="prog"><div class="prog-fill" style="width:${l.status === "done" ? 100 : 0}%"></div></div>
      </div>`).join("");
    root.innerHTML = `
      <div class="plan-summary">
        <div class="plan-date">${esc(latest.name || "匿名学习者")} 的今日进度（${esc(latest.date)}）</div>
        <div class="plan-pct">${s.percent || 0}%<small>（${s.done || 0}/${s.total || 0} 节${s.skipped ? ` · 跳过 ${s.skipped}` : ""}）</small></div>
      </div>
      <div class="prog big"><div class="prog-fill" style="width:${s.percent || 0}%"></div></div>
      ${lessons || `<div class="notice empty">快照里没有课程明细。</div>`}`;
  }

  function connect() {
    const root = document.getElementById("status-root");
    const meta = document.getElementById("status-meta");
    const topic = new URLSearchParams(location.search).get("topic");
    if (!topic) {
      root.innerHTML = `<div class="notice empty"><strong>缺少监视链接参数。</strong>请使用打卡生成的完整链接（含 ?topic=…）打开本页。</div>`;
      return;
    }
    if (es) es.close();
    root.innerHTML = `<div class="notice info">正在连接实时频道…</div>`;
    try {
      es = new EventSource(`${CLOUD}/${topic}/sse?since=12h`);
      es.onmessage = ev => {
        try {
          const m = JSON.parse(ev.data);
          if (m.event !== "message" || !m.message) return;
          latest = JSON.parse(m.message);
          if (latest && latest.app === "yyy-prep-checkin") render();
        } catch (e) { /* 非打卡消息忽略 */ }
      };
      es.onerror = () => {
        meta.textContent = "实时连接断开，自动重连中…（也可点「立即刷新」）";
      };
    } catch (e) {
      root.innerHTML = `<div class="notice empty"><strong>无法建立实时连接（${esc(e.message)}）。</strong>请检查网络后点「立即刷新」重试。</div>`;
    }
  }

  document.addEventListener("DOMContentLoaded", () => {
    if (!document.getElementById("status-root")) return;
    connect();
    document.getElementById("status-refresh").addEventListener("click", connect);
  });
})();
